mapper.select:
select count(*) from eng_article a where a.create_by=#{username}
and exists(select 1 from eng_article_word_rel r where r.article_id=a.id and r.level_no is not null)
and not exists(select 1 from (select distinct article_id,level_no from eng_article_word_rel where level_no is not null) levels
  left join eng_article_level_progress p on p.article_id=levels.article_id and p.level_no=levels.level_no and p.user_id=#{userId}
  where levels.article_id=a.id and coalesce(p.highest_stars,0)<1 and coalesce(p.completed_by_known_words,0)=0)
